import { useEffect, useState } from "react";
import { useAuth } from "../../../../auth/AuthContext";
import { CopyButton } from "../../../../components/Copy";
import { Dialog } from "../../../../components/Dialog";
import { Alert, Button, InlineError, Mono, Segmented, TextField } from "../../../../components/ui";
import type { ResetResult, UserRow } from "./types";
import { confirmFor, useWinmod } from "./useWinmod";

/**
 * Reset a password (ADR-0075 section 2). Typed or generated by the server; either way it travels sealed. A generated one
 * is shown here once, with a copy button, and cleared when the dialog closes: nothing shows it again.
 */
export function ResetPasswordDialog({
  deviceId,
  minLength,
  user,
  onClose,
}: {
  deviceId: string;
  minLength: number;
  user: UserRow | null;
  onClose: (changed: boolean) => void;
}) {
  const { can } = useAuth();
  const run = useWinmod(deviceId);
  const [how, setHow] = useState<"generate" | "type">("generate");
  const [password, setPassword] = useState("");
  const [mustChange, setMustChange] = useState(true);
  const [unlock, setUnlock] = useState(false);
  const [typed, setTyped] = useState("");
  const [service, setService] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<unknown>(null);
  const [refusal, setRefusal] = useState<string | null>(null);
  const [shown, setShown] = useState<{ generated: string | null; result: ResetResult } | null>(null);
  useEffect(() => {
    setHow("generate");
    setPassword("");
    setMustChange(true);
    setUnlock(false);
    setTyped("");
    setService("");
    setError(null);
    setRefusal(null);
    setShown(null);
  }, [user]);
  if (!user) return <Dialog open={false} onClose={() => undefined} title="" />;
  const isService = user.protection === "service";
  const long = Math.max(8, minLength);
  const ready =
    typed === user.sam &&
    (how === "generate" || password.length >= long) &&
    (!isService || service === `service-account:${user.sam}`);

  const submit = async () => {
    setBusy(true);
    setError(null);
    setRefusal(null);
    try {
      const params: Record<string, unknown> = { id: user.id, mustChange, unlock };
      if (how === "type") params.password = password;
      if (isService) params.serviceConfirm = service;
      const r = await run<ResetResult>("user_reset_password", params, confirmFor("user_reset_password", user.id));
      // The typed password is not kept past this call.
      setPassword("");
      if (r.ok && r.data) setShown({ generated: r.generated?.password ?? null, result: r.data });
      else setRefusal(r.failure?.message ?? "The controller refused.");
    } catch (e) {
      setError(e);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Dialog
      open
      onClose={() => onClose(shown !== null)}
      dismissible={!busy}
      title={`Reset the password of ${user.name}`}
      description="The password goes to the controller sealed and is never written to a log or shown again."
      footer={
        shown ? (
          <Button variant="primary" onClick={() => onClose(true)}>
            Close
          </Button>
        ) : (
          <>
            <Button onClick={() => onClose(false)}>Cancel</Button>
            <Button variant="danger" onClick={() => void submit()} loading={busy} disabled={!ready}>
              Reset password
            </Button>
          </>
        )
      }
    >
      {shown ? (
        <div className="flex flex-col gap-3">
          <Alert tone="ok">
            The password was changed.{" "}
            {shown.result.mustChange ? "They must choose a new one at the next sign-in. " : ""}
            {shown.result.unlocked ? "The account was unlocked. " : ""}
            Other controllers may take a few moments to learn it, so a first try at another controller can fail.
          </Alert>
          {shown.generated && (
            <div className="flex flex-col gap-2">
              <p className="text-sm text-fg">Give them this password. It is shown now and not again.</p>
              <div className="flex flex-wrap items-center gap-2">
                <Mono className="rounded border border-line bg-surface px-2 py-1 text-base select-all">{shown.generated}</Mono>
                <CopyButton text={shown.generated} />
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="flex flex-col gap-3">
          <Segmented
            label="Password"
            value={how}
            onChange={setHow}
            options={[
              { value: "generate", label: "Generate one" },
              { value: "type", label: "Type one" },
            ]}
          />
          {how === "type" && (
            <TextField
              label="New password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="new-password"
              hint={`At least ${long} characters; the domain's policy decides the rest.`}
            />
          )}
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={mustChange} onChange={(e) => setMustChange(e.target.checked)} /> They must change it at the next sign-in
          </label>
          <label className="flex items-center gap-2 text-sm">
            <input type="checkbox" checked={unlock} onChange={(e) => setUnlock(e.target.checked)} /> Unlock the account too
          </label>
          {isService && (
            <Alert tone="warn" title="This looks like a service account">
              {user.reason}. Resetting its password can stop the services that run as it.
              {!can("ad.reset_password") && " Only an administrator can confirm this."}
            </Alert>
          )}
          <TextField label={`Type ${user.sam} to confirm`} value={typed} onChange={(e) => setTyped(e.target.value)} autoComplete="off" />
          {isService && (
            <TextField label={`Type service-account:${user.sam} to confirm it is a service account`} value={service} onChange={(e) => setService(e.target.value)} autoComplete="off" />
          )}
          <InlineError error={error} />
          {refusal && <Alert tone="danger">{refusal}</Alert>}
        </div>
      )}
    </Dialog>
  );
}
